\begin{verbatim}
\section{快速终端滑模控制器设计方案}

\subsection{系统建模}
\subsubsection{动力学方程}
基于教材中的3-DOF机械臂动力学模型，第一关节的动力学方程为：
$$
\ddot{\theta}_1 = \frac{1}{J_1} \left( \tau_1 - b_1 \dot{\theta}_1 - c_1 \theta_1 \right)
$$
其中，$J_1$为第一关节惯量，$b_1$为阻尼系数，$c_1$为弹簧系数，$\tau_1$为驱动力矩。

\subsubsection{状态空间表示}
定义状态变量 $x_1 = \theta_1, x_2 = \dot{\theta}_1$。系统状态方程为：
$$
\dot{x}_1 = x_2 \\
\dot{x}_2 = \frac{1}{J_1} \left( \tau_1 - b_1 x_2 - c_1 x_1 \right)
$$
\subsection{控制器选型与设计}
\subsubsection{滑模面设计}
定义跟踪误差 $e_1 = \theta_1 - \theta_{1d}$，速度误差 $\dot{e}_1 = \dot{\theta}_1 - \dot{\theta}_{1d}$。
选择滑模面 $s = \dot{e}_1 + \lambda e_1$，其中 $\lambda > 0$。
\subsubsection{快速终端滑模控制器}
控制器设计为：
$$
\tau_1 = J_1 \left( \ddot{\theta}_{1d} - \lambda \dot{e}_1 - \eta \text{sgn}(s) \right) + b_1 \dot{\theta}_1 + c_1 \theta_1
$$
其中 $\eta > 0$为滑模增益。
\subsection{参数整定}
\subsubsection{滑模增益 $\eta$}
根据初始误差 $e_1(0) = 0.35$ rad，选择 $\eta = 0.5$。
\subsubsection{带宽参数 $\lambda$}
选择 $\lambda = 10$。
\subsection{性能验证}
\subsubsection{有限时间收敛性}
通过Lyapunov函数分析，可证明系统在有限时间 $T$ 内收敛至零误差。
\subsubsection{仿真结果}
在仿真中，系统在 $T \approx 1.5$ 秒内到达滑动面，并收敛至零误差。
\subsection{工程考量}
\subsubsection{抖振抑制}
使用饱和函数代替sgn函数，可有效抑制抖振。
\subsubsection{参数辨识}
需对 $J_1, b_1, c_1$ 进行精确辨识，以保证控制性能。
\end{verbatim}

